const __SITE_DETAIL_DATA = {"services":{"implants":{"cat":"Restorative","title":"Dental Implants","img":"assets/service-implants.jpg","paras":["Transformative dental implants that look, feel, and function like natural teeth. From single implants to full arch implant-supported dentures, The House of Dental offers tooth replacement solutions that are long-lasting, luminous, and made especially for you.","Dr. Patel is a leader in computer-assisted dentistry and minimally invasive guided surgeries, and a fellow of the International Congress of Oral Implantologists. Implant Special for patients without insurance: from $2,998 — implant, abutment, and crown included."],"items":["Single tooth implants","Implant-supported bridges","Full arch implant-supported dentures","Guided, minimally invasive placement"]},"restorative":{"cat":"Restorative","title":"Full Mouth Restoration","img":"assets/service-restoration.jpg","paras":["Comprehensive one-day restorations that rebuild the health, function, and natural beauty of your smile. We use top-quality materials and technologies to ensure the best, healthiest outcomes — with customized care tailored to your needs at every step."],"items":["Precision-crafted restorations","Specialty porcelain work","Comprehensive treatment planning"]},"crowns":{"cat":"CEREC® Technology","title":"Same-Day Dental Crowns","img":"assets/service-crowns.jpg","paras":["The CEREC system allows us to craft the highest quality crowns right here in our dental office, in a single visit. No temporary restorations. No follow-up appointments. Just a precision-crafted, permanent crown — the same day you walk in."],"items":[]},"dentures":{"cat":"Restorative","title":"Dentures","img":"assets/service-dentures.jpg","paras":["From removable dentures to full arch implant-supported dentures, we design comfortable, natural-looking tooth replacement that restores your ability to eat, speak, and smile with total confidence."],"items":[]},"root-canals":{"cat":"Restorative","title":"Root Canals","img":"assets/service-root-canals.jpg","paras":["Gentle, modern root canal therapy that relieves pain and saves your natural tooth. With fully digital imaging and a calm, patient-first approach, the experience is far more comfortable than its reputation."],"items":[]},"cosmetic":{"cat":"Cosmetic","title":"Cosmetic Dentistry","img":"assets/service-cosmetic.jpg","paras":["Want a more confident smile? Learn how porcelain veneers, dental crowns, or a complete smile makeover could give you a glowing smile designed around your features."],"items":[]},"veneers":{"cat":"Cosmetic","title":"Porcelain Veneers","img":"assets/service-veneers.jpg","paras":["Specialty porcelain restorations, individually crafted to reshape, brighten, and perfect your smile — with results that photograph beautifully and last for years."],"items":[]},"preventive":{"cat":"Preventive","title":"Preventive Care & Cleanings","img":"assets/service-preventive.jpg","paras":["Customized preventive care and oral health education. Our hygienists never rush — every cleaning is thorough, comfortable, and tailored to keeping your teeth and gums healthy for life."],"items":[]},"invisalign":{"cat":"Orthodontic","title":"Invisalign®","img":"assets/service-invisalign.jpg","paras":["Invisalign clear braces for teens and adults. Straighten your teeth discreetly with removable, nearly invisible aligners — no brackets, no wires, no interruptions to your life."],"items":[]},"oral-surgery":{"cat":"Surgical","title":"Oral Surgery","img":"assets/service-oral-surgery.jpg","paras":["From extractions to surgical implant placement, oral surgery at The House of Dental is performed with precision, advanced imaging, and genuine care for your comfort."],"items":[]},"sedation":{"cat":"Comfort","title":"Sedation Dentistry","img":"assets/service-sedation.jpg","paras":["Dental anxiety should never stand between you and a healthy smile. Our sedation options keep you calm and comfortable through any procedure — many patients barely remember their visit."],"items":[]},"tmj":{"cat":"Therapeutic","title":"TMJ Treatment","img":"assets/service-tmj.jpg","paras":["Jaw pain, clicking, and tension headaches often trace back to the temporomandibular joint. We diagnose and treat TMJ disorders to relieve pain and restore comfortable function."],"items":[]},"srp":{"cat":"Periodontal","title":"Scaling &amp; Root Planing","img":"assets/service-srp.jpg","paras":["Also called a deep cleaning, scaling and root planing treats gum disease below the gumline — removing hardened plaque and tartar from the tooth roots, then smoothing those root surfaces so the gum tissue can reattach and heal.","Left untreated, periodontal disease is the leading cause of adult tooth loss. Caught and managed early, it's highly controllable. Treatment is typically done by quadrant with local anesthetic for comfort, followed by periodontal maintenance visits to keep it stable."],"items":["Deep cleaning below the gumline","Root surface smoothing for tissue reattachment","Reduced pocket depths","Ongoing periodontal maintenance"]},"quietnite":{"cat":"Oral Appliance","title":"QuietNite Sleep","img":"assets/service-quietnite.jpg","paras":["The QuietNite is a custom mandibular advancement device for snoring and mild to moderate obstructive sleep apnea in adults. Two thermally formed trays fit over the upper and lower arches, joined by lateral connectors that gently hold the lower jaw forward during sleep.","Advancing the jaw increases the three-dimensional space in the airway, reducing air velocity and the soft-tissue vibration that causes snoring. The connectors are patient-adjustable at home, so comfort and effectiveness can be dialed in over time.","For many patients an oral appliance is far easier to live with than CPAP — no mask, no hose, no power source. If you've been diagnosed with severe sleep apnea, we coordinate with your physician rather than replacing prescribed therapy."],"items":["Custom fabricated from digital scans","Patient-adjustable jaw advancement","Treats snoring and mild to moderate OSA","A comfortable alternative to CPAP for many patients"]}},"technology":{"cerec":{"cat":"Chairside Milling","title":"CEREC® Same-Day Crowns","img":"assets/technology-cerec.jpg","paras":["CEREC lets us design, mill, and place a permanent ceramic crown in a single appointment. A digital scan of your tooth becomes a 3D model on screen, and our in-office milling unit carves the restoration from a solid block of ceramic while you wait.","The result: no impression putty, no temporary crown to fall off, and no second appointment weeks later. You walk in with a damaged tooth and walk out with a finished, color-matched restoration."],"soon":false},"ct-scan":{"cat":"3D Imaging","title":"CT Scan (Cone Beam)","img":"assets/technology-ct-scan.jpg","paras":["Our cone beam CT scanner captures a complete three-dimensional view of your teeth, jaw, nerves, and sinuses in a single rotation — detail a traditional two-dimensional X-ray simply cannot show.","This is what makes guided implant surgery possible. Dr. Patel can measure bone density and volume, map the exact position of nerves, and plan the precise angle and depth of an implant before ever beginning the procedure. It means fewer surprises, less invasive surgery, and more predictable outcomes."],"soon":false},"digital-scans":{"cat":"Fully Digital","title":"Digital Scans & X-Rays","img":"assets/technology-digital-scans.jpg","paras":["We replaced messy impression trays with a handheld intraoral scanner that builds a precise digital model of your mouth in minutes — more comfortable, more accurate, and instantly viewable on screen.","Our digital radiographs use significantly less radiation than traditional film X-rays and appear immediately, so Dr. Patel can show you exactly what he's seeing and explain it in real time."],"soon":false},"guided-surgery":{"cat":"Implantology","title":"Computer-Guided Surgery","img":"assets/technology-guided-surgery.jpg","paras":["Using CT data, implant placement is planned digitally down to the millimeter, then executed with a custom surgical guide that directs the placement exactly as planned.","Because the position is determined before surgery begins, the procedure is more precise and far less invasive — often meaning smaller incisions, less discomfort, and a faster recovery than freehand placement."],"soon":false},"deka":{"cat":"Laser Aesthetics","title":"DEKA CO2 Facial Resurfacing Laser","img":"assets/co2-laser.jpg","paras":["DEKA is a leading name in medical laser technology, used for skin resurfacing and rejuvenation treatments that address fine lines, uneven texture, sun damage, pigmentation, and scarring.","The laser works by delivering precisely controlled energy to the skin, stimulating the body's natural collagen production and encouraging fresh, healthy tissue to replace damaged surface layers — with treatment intensity tailored to each patient's skin and goals."],"soon":false},"emage":{"cat":"Diagnostic Imaging","title":"Emage 3D Skin Scanner","img":"assets/skin-analysis.jpg","paras":["The Emage scanner captures a detailed three-dimensional analysis of your skin — revealing sun damage, pigmentation, pore condition, wrinkles, and texture beneath the surface that the naked eye cannot detect.","It turns aesthetic treatment into something measurable. We can establish an objective baseline before treatment begins, build a plan around what your skin actually needs, and show you side-by-side progress over time rather than asking you to guess at the results."],"soon":false},"hydroderm":{"cat":"Signature Treatment","title":"Custom HydroDerm Facials","img":"assets/hydroderm-facial.jpg","paras":["A multi-step hydrating facial treatment that cleanses, gently exfoliates, extracts impurities, and infuses the skin with hydrating serums — all in one session, with no downtime.","Each facial is customized rather than one-size-fits-all: the serums and intensity are selected based on your skin's needs, which is where the Emage scanner comes in. Results are immediate — smoother texture, refined pores, and a visible glow."],"soon":false},"microneedling":{"cat":"Collagen Induction","title":"Microneedling","img":"assets/microneedling.jpg","paras":["Microneedling &mdash; collagen induction therapy &mdash; uses a precision device to create thousands of microscopic channels in the skin, triggering the body's natural wound-healing cascade.","As the skin repairs those channels it produces fresh collagen and elastin, softening acne scars, refining texture, tightening pores, and firming skin from within. Because it works without heat, it's safe across all skin types."],"soon":false}}};
const __SITE_ANALYTICS = {"provider":"gtag","enabled":false,"measurementId":"","consent":{"mode":"advanced","version":2,"storageKey":"thod-analytics-consent","waitForUpdate":500}};
