(() => {
  const reduced = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const header = document.querySelector("header.site");
  const setHeaderHeight = () => header && document.documentElement.style.setProperty("--head-h", `${header.offsetHeight}px`);
  setHeaderHeight();
  addEventListener("resize", setHeaderHeight);
  document.fonts?.ready.then(setHeaderHeight);

  const reveal = "IntersectionObserver" in window ? new IntersectionObserver((entries) => {
    for (const entry of entries) if (entry.isIntersecting) {
      entry.target.classList.add("in");
      reveal.unobserve(entry.target);
    }
  }, { threshold: 0.16 }) : null;
  document.querySelectorAll(".rv, .rv-img, .rv-line").forEach((element) => reveal ? reveal.observe(element) : element.classList.add("in"));

  const hero = document.querySelector(".hero-bg");
  if (hero && !reduced) addEventListener("scroll", () => {
    hero.style.transform = `translateY(${scrollY * 0.28}px)`;
  }, { passive: true });

  const animateCounter = (element) => {
    const target = Number.parseFloat(element.dataset.count);
    if (!Number.isFinite(target)) return;
    const decimals = (element.dataset.count.split(".")[1] || "").length;
    const suffix = element.dataset.suffix || "";
    if (reduced) return void (element.textContent = `${element.dataset.count}${suffix}`);
    const start = performance.now();
    const tick = (time) => {
      const progress = Math.min((time - start) / 1600, 1);
      const value = target * (1 - Math.pow(1 - progress, 3));
      element.textContent = `${value.toFixed(decimals)}${suffix}`;
      if (progress < 1) requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  };
  const counterObserver = "IntersectionObserver" in window ? new IntersectionObserver((entries) => {
    for (const entry of entries) if (entry.isIntersecting) {
      animateCounter(entry.target);
      counterObserver.unobserve(entry.target);
    }
  }, { threshold: 0.6 }) : null;
  document.querySelectorAll("[data-count]").forEach((counter) => counterObserver ? counterObserver.observe(counter) : animateCounter(counter));

  const careBack = document.querySelector('.care-back-to-top');
  if (careBack) {
    const updateCareBack = () => {
      const visible = scrollY > innerHeight;
      careBack.classList.toggle('is-visible', visible);
      careBack.setAttribute('aria-hidden', String(!visible));
      careBack.tabIndex = visible ? 0 : -1;
    };
    updateCareBack();
    addEventListener('scroll', updateCareBack, { passive: true });
  }

  const booking = document.querySelector('#book');
  if (booking) {
    document.querySelectorAll('[data-appointment-form] input, [data-appointment-form] select, [data-appointment-form] textarea').forEach((field) => {
      field.addEventListener('focus', () => document.body.classList.add('booking-focus'));
      field.addEventListener('blur', () => document.body.classList.remove('booking-focus'));
    });
  }

  const alignCareHash = () => {
    if (!document.querySelector('.care-block')) return;
    const target = document.getElementById(location.hash.slice(1));
    if (!target) return;
    requestAnimationFrame(() => requestAnimationFrame(() => target.scrollIntoView({ block: 'start' })));
  };
  if (document.querySelector('.care-block')) {
    alignCareHash();
    addEventListener('hashchange', alignCareHash);
  }
})();

(() => {
  const button = document.querySelector(".burger");
  const menu = document.querySelector(".menu");
  if (button && menu) {
    const focusable = () => [...menu.querySelectorAll('a, button, [tabindex]:not([tabindex="-1"])')];
    const setBackgroundInert = (inert) => document.querySelectorAll('body > :not(.menu):not(.site)').forEach((element) => { element.inert = inert; });
    let returnFocus;
    const close = () => {
      button.classList.remove("open");
      menu.classList.remove("open");
      button.setAttribute("aria-expanded", "false");
      button.setAttribute("aria-label", "Open menu");
      document.body.style.overflow = "";
      menu.setAttribute("aria-hidden", "true");
      setBackgroundInert(false);
      returnFocus?.focus();
    };
    button.addEventListener("click", () => {
      const open = !menu.classList.contains("open");
      button.classList.toggle("open", open);
      menu.classList.toggle("open", open);
      button.setAttribute("aria-expanded", String(open));
      button.setAttribute("aria-label", open ? "Close menu" : "Open menu");
      document.body.style.overflow = open ? "hidden" : "";
      menu.setAttribute("aria-hidden", String(!open));
      setBackgroundInert(open);
      if (open) { returnFocus = document.activeElement; focusable()[0]?.focus(); }
    });
    menu.querySelectorAll("a").forEach((link) => link.addEventListener("click", close));
    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape" && menu.classList.contains("open")) {
        close();
        button.focus();
      }
      if (event.key === "Tab" && menu.classList.contains("open")) {
        const items = focusable();
        if (!items.length) return;
        const first = items[0]; const last = items[items.length - 1];
        if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
        else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
      }
    });
  }
  const current = location.pathname.split("/").pop() || "index.html";
  document.querySelectorAll("[data-primary-link]").forEach((link) => {
    const paths = [link.getAttribute("href"), ...(link.dataset.activePaths?.split(/\s+/) || [])]
      .filter(Boolean)
      .map((path) => path.split("#")[0]);
    const active = paths.includes(current);
    link.classList.toggle("active", active);
    if (active) link.setAttribute("aria-current", "page");
    else link.removeAttribute("aria-current");
  });

  // Mobile browsers can restore the previous scroll position after following a
  // cross-page hash link. Reapply the selected care section once the guide has
  // finished laying out so Treatment Care links always reveal their section.
  const careSections = [...document.querySelectorAll(".care-block[id]")];
  const mobileCareGuide = window.matchMedia("(max-width: 800px)");
  const scrollToCareSection = () => {
    if (!mobileCareGuide.matches || !location.hash || !careSections.length) return;
    const target = careSections.find((section) => `#${section.id}` === location.hash);
    if (!target) return;
    requestAnimationFrame(() => requestAnimationFrame(() => target.scrollIntoView({ block: "start" })));
  };
  if (careSections.length) {
    scrollToCareSection();
    window.addEventListener("hashchange", scrollToCareSection);
    window.addEventListener("pageshow", scrollToCareSection);
  }

  const booking = document.querySelector("#book");
  const alignBookingHash = () => {
    if (!booking || location.hash !== "#book") return;
    requestAnimationFrame(() => requestAnimationFrame(() => booking.scrollIntoView({ block: "start" })));
  };
  if (booking) {
    alignBookingHash();
    addEventListener("hashchange", alignBookingHash);
    addEventListener("load", alignBookingHash);
    addEventListener("pageshow", alignBookingHash);
  }
})();

(() => {
  const quotes = [...document.querySelectorAll("[data-quote]")];
  const dots = [...document.querySelectorAll(".quote-dot")];
  if (!quotes.length) return;
  const reduced = matchMedia("(prefers-reduced-motion: reduce)").matches;
  let index = 0;
  let timer;
  const show = (next) => {
    index = next;
    quotes.forEach((quote, position) => {
      quote.hidden = position !== next;
      quote.classList.toggle("in", position === next);
    });
    dots.forEach((dot, position) => {
      dot.classList.toggle("on", position === next);
      dot.setAttribute("aria-pressed", String(position === next));
    });
  };
  const start = () => {
    if (!reduced) timer = setInterval(() => show((index + 1) % quotes.length), 7000);
  };
  dots.forEach((dot, position) => dot.addEventListener("click", () => {
    clearInterval(timer);
    show(position);
    start();
  }));
  show(0);
  start();
})();

(() => {
  document.querySelectorAll(".ba").forEach((comparison, index) => {
    const after = comparison.querySelector(".after-wrap");
    const handle = comparison.querySelector(".handle");
    if (!after || !handle) return;
    let value = 50;
    const render = () => {
      after.style.clipPath = `inset(0 0 0 ${value}%)`;
      handle.style.left = `${value}%`;
      handle.setAttribute("aria-valuenow", String(Math.round(value)));
    };
    const setFromPointer = (clientX) => {
      const rect = comparison.getBoundingClientRect();
      value = Math.max(4, Math.min(96, ((clientX - rect.left) / rect.width) * 100));
      render();
    };
    handle.tabIndex = 0;
    handle.setAttribute("role", "slider");
    handle.setAttribute("aria-label", `Before and after comparison ${index + 1}`);
    handle.setAttribute("aria-valuemin", "4");
    handle.setAttribute("aria-valuemax", "96");
    comparison.addEventListener("pointerdown", (event) => {
      comparison.setPointerCapture(event.pointerId);
      setFromPointer(event.clientX);
    });
    comparison.addEventListener("pointermove", (event) => {
      if (comparison.hasPointerCapture(event.pointerId)) setFromPointer(event.clientX);
    });
    handle.addEventListener("keydown", (event) => {
      if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return;
      event.preventDefault();
      if (event.key === "Home") value = 4;
      else if (event.key === "End") value = 96;
      else value = Math.max(4, Math.min(96, value + (event.key === "ArrowRight" ? 5 : -5)));
      render();
    });
    render();
  });
})();

(() => {
  const definitions = [
    { dialog: "svcmodal", trigger: ".svc-card", key: "svc", kind: "service", prefix: "svcm" },
    { dialog: "techmodal", trigger: ".tech-card", key: "tech", kind: "technology", prefix: "techm" }
  ];

  definitions.forEach((definition) => {
    const dialog = document.getElementById(definition.dialog);
    if (!dialog) return;

    document.body.classList.add("js-enhanced");
    const image = document.getElementById(`${definition.prefix}-img`);
    const category = document.getElementById(`${definition.prefix}-cat`);
    const title = document.getElementById(`${definition.prefix}-title`);
    const body = document.getElementById(`${definition.prefix}-body`);
    const panel = dialog.querySelector(".panel");
    const previous = definition.kind === "service" ? dialog.querySelector("[data-modal-prev]") : null;
    const next = definition.kind === "service" ? dialog.querySelector("[data-modal-next]") : null;
    let returnFocus;
    let activeTrigger;
    let transitionTimer;
    let touchStart = null;
    let inerted = [];

    const detailData = definition.kind === "service"
      ? { ...(__SITE_DETAIL_DATA?.services || {}), ...(__SITE_DETAIL_DATA?.technology || {}) }
      : __SITE_DETAIL_DATA?.technology || {};
    const decode = (value = "") => {
      return new DOMParser().parseFromString(value, "text/html").body.textContent || "";
    };
    const getDetail = (id) => detailData[id];
    const getTrigger = (id) => document.querySelector(`${definition.trigger}[data-${definition.key}="${CSS.escape(id)}"]`);
    const getTriggers = () => [...document.querySelectorAll(definition.trigger)].filter((trigger) => getDetail(trigger.dataset[definition.key]));
    const inertBackground = () => {
      if (inerted.length) return;
      const modalMain = dialog.closest("main");
      const background = [
        ...document.querySelectorAll("body > header, body > footer, body > .mobile-actions"),
        ...(modalMain ? [...modalMain.children].filter((element) => element !== dialog) : [])
      ];
      inerted = background.map((element) => ({ element, inert: element.inert }));
      background.forEach((element) => { element.inert = true; });
    };
    const close = () => {
      if (transitionTimer) {
        clearTimeout(transitionTimer);
        transitionTimer = null;
      }
      panel?.classList.remove("is-switching");
      panel?.style.removeProperty("--modal-shift");
      dialog.classList.remove("open");
      document.body.classList.remove("modal-open");
      inerted.forEach(({ element, inert }) => { element.inert = inert; });
      inerted = [];
      returnFocus?.focus();
      returnFocus = null;
    };
    const render = (detail, resolvedTrigger, focusClose) => {
      returnFocus = resolvedTrigger || document.activeElement;
      activeTrigger = resolvedTrigger;
      image.src = detail.img;
      const cardTitle = resolvedTrigger?.querySelector("h3")?.textContent;
      const displayTitle = cardTitle || detail.title;
      image.alt = decode(displayTitle);
      category.textContent = decode(detail.cat);
      title.textContent = decode(displayTitle);
      const fragment = document.createDocumentFragment();
      (detail.paras || []).forEach((paragraph) => {
        const element = document.createElement("p");
        element.textContent = decode(paragraph);
        fragment.append(element);
      });
      if (detail.items?.length) {
        const list = document.createElement("ul");
        detail.items.forEach((item) => {
          const element = document.createElement("li");
          element.textContent = decode(item);
          list.append(element);
        });
        fragment.append(list);
      }
      if (detail.soon) {
        const note = document.createElement("p");
        note.className = "soon-note";
        note.append(document.createTextNode("This service is coming soon to The House of Dental. Call "));
        const phone = document.createElement("a");
        phone.href = "tel:+14076781400";
        phone.textContent = "(407) 678-1400";
        note.append(phone, document.createTextNode(" to be notified when it launches."));
        fragment.append(note);
      }
      body.replaceChildren(fragment);
      dialog.classList.add("open");
      document.body.classList.add("modal-open");
      inertBackground();
      if (focusClose) window.setTimeout(() => dialog.querySelector("button.close[data-close]")?.focus(), 0);
    };
    const open = (id, trigger, { focusClose = true, transition = false, direction = 1 } = {}) => {
      const detail = getDetail(id);
      if (!detail) return;
      if (transitionTimer) {
        clearTimeout(transitionTimer);
        transitionTimer = null;
      }
      const resolvedTrigger = trigger || getTrigger(id);
      const prefersReducedMotion = window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches;
      const canTransition = transition && panel && dialog.classList.contains("open") && !prefersReducedMotion;
      if (!canTransition) {
        panel?.classList.remove("is-switching");
        panel?.style.removeProperty("--modal-shift");
        render(detail, resolvedTrigger, focusClose);
        return;
      }
      panel.style.setProperty("--modal-shift", direction > 0 ? "1.2rem" : "-1.2rem");
      panel.classList.add("is-switching");
      transitionTimer = window.setTimeout(() => {
        transitionTimer = null;
        render(detail, resolvedTrigger, focusClose);
        window.requestAnimationFrame(() => {
          panel.classList.remove("is-switching");
          panel.style.removeProperty("--modal-shift");
        });
      }, 180);
    };
    const navigate = (direction, control) => {
      const triggers = getTriggers();
      if (!triggers.length) return;
      const currentIndex = Math.max(0, activeTrigger ? triggers.indexOf(activeTrigger) : 0);
      const nextIndex = (currentIndex + direction + triggers.length) % triggers.length;
      const target = triggers[nextIndex];
      const id = target.dataset[definition.key];
      history.replaceState(null, "", `#${id}`);
      open(id, target, { focusClose: false, transition: true, direction });
      control?.focus();
    };

    document.querySelectorAll(definition.trigger).forEach((trigger) => {
      trigger.setAttribute("aria-haspopup", "dialog");
      trigger.addEventListener("click", (event) => {
        event.preventDefault();
        const id = trigger.dataset[definition.key];
        history.pushState(null, "", `#${id}`);
        open(id, trigger);
      });
    });
    dialog.querySelectorAll("[data-close]").forEach((element) => element.addEventListener("click", close));
    dialog.addEventListener("touchstart", (event) => {
      const touch = event.changedTouches[0];
      touchStart = { x: touch.clientX, y: touch.clientY };
    }, { passive: true });
    dialog.addEventListener("touchend", (event) => {
      if (!touchStart) return;
      const touch = event.changedTouches[0];
      const dx = touch.clientX - touchStart.x;
      const dy = touch.clientY - touchStart.y;
      touchStart = null;
      if (Math.abs(dx) < 56 || Math.abs(dx) < Math.abs(dy) * 1.25) return;
      navigate(dx < 0 ? 1 : -1);
    }, { passive: true });
    previous?.addEventListener("click", () => navigate(-1, previous));
    next?.addEventListener("click", () => navigate(1, next));
    document.addEventListener("keydown", (event) => {
      if (!dialog.classList.contains("open")) return;
      if (event.key === "Escape") close();
      if (event.key === "Tab") {
        const items = [...dialog.querySelectorAll('button, a, [tabindex]:not([tabindex="-1"])')].filter((element) => !element.disabled);
        if (items.length) {
          const first = items[0]; const last = items[items.length - 1];
          if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
          else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
        }
      }
      if (definition.kind !== "service") return;
      if (event.key === "ArrowLeft") {
        event.preventDefault();
        navigate(-1);
      }
      if (event.key === "ArrowRight") {
        event.preventDefault();
        navigate(1);
      }
    });

    const openHash = () => {
      const id = location.hash.slice(1).split("/").pop();
      if (getDetail(id)) open(id, getTrigger(id));
    };
    addEventListener("hashchange", openHash);
    addEventListener("popstate", openHash);
    openHash();
  });
})();

(() => {
  const range = document.getElementById("chr-range");
  if (!range) return;
  const amount = document.getElementById("chr-amt");
  const biweekly = document.getElementById("chr-bi");
  const months24 = document.getElementById("chr-24");
  const months60 = document.getElementById("chr-60");
  const money = (value) => `$${Math.round(value).toLocaleString()}`;
  const setPlan = (element, value, suffix) => {
    element.replaceChildren(document.createTextNode(value));
    const detail = document.createElement("i");
    detail.textContent = suffix;
    element.appendChild(detail);
  };
  const update = () => {
    const value = Number.parseInt(range.value, 10);
    amount.textContent = money(value);
    if (value <= 3000) setPlan(biweekly, money(value / 4), "×4");
    else setPlan(biweekly, "Over $3,000", "");
    setPlan(months24, money(value / 24), "/mo");
    setPlan(months60, money(value / 60), "/mo");
  };
  range.addEventListener("input", update);
  update();
})();

(() => {
  const form = document.querySelector("form[data-appointment-form]");
  if (!form) return;

  const button = form.querySelector("button[type='submit']");
  const status = document.querySelector("#appointment-status");
  const setStatus = (message, state) => {
    if (!status) return;
    status.textContent = message;
    status.dataset.state = state;
  };

  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    if (button?.disabled) return;
    button?.setAttribute("aria-busy", "true");
    if (button) button.disabled = true;
    setStatus("Sending your request…", "pending");

    try {
      const response = await fetch(form.action, {
        method: "POST",
        headers: { Accept: "application/json", "Content-Type": "application/x-www-form-urlencoded;charset=UTF-8" },
        body: new URLSearchParams(new FormData(form))
      });
      const result = await response.json().catch(() => ({}));
      if (!response.ok || result.ok !== true) throw new Error(result.error || "Request failed");
      form.reset();
      setStatus(result.message || "Your request was sent. The office will call to confirm.", "success");
    } catch {
      setStatus("We couldn't send your request online. Please call (407) 678-1400.", "error");
    } finally {
      button?.removeAttribute("aria-busy");
      if (button) button.disabled = false;
      status?.focus({ preventScroll: true });
    }
  });
})();

(() => {
  document.querySelectorAll("img").forEach((image, index) => {
    image.decoding = "async";
    if (index > 0 && !image.classList.contains("logo-img")) image.loading ||= "lazy";
    const failed = () => image.setAttribute("data-failed", "true");
    image.addEventListener("error", failed, { once: true });
    if (image.complete && image.naturalWidth === 0) failed();
  });
})();

(() => {
  const config = __SITE_ANALYTICS;
  const consentConfig = config?.consent;
  if (
    config?.provider !== "gtag"
    || config.enabled !== true
    || consentConfig?.mode !== "advanced"
    || consentConfig.version !== 2
    || !/^G-[A-Z0-9]+$/i.test(config.measurementId)
  ) return;

  const storageKey = consentConfig.storageKey || "thod-analytics-consent";
  const validChoices = new Set(["granted", "denied"]);
  const readChoice = () => {
    try {
      const choice = localStorage.getItem(storageKey);
      return validChoices.has(choice) ? choice : null;
    } catch {
      return null;
    }
  };
  const saveChoice = (choice) => {
    try {
      localStorage.setItem(storageKey, choice);
    } catch {
      // Consent still applies to the current page if storage is unavailable.
    }
  };
  const defaultConsent = {
    ad_storage: "denied",
    ad_user_data: "denied",
    ad_personalization: "denied",
    analytics_storage: "denied"
  };
  const consentFor = (choice) => ({
    ...defaultConsent,
    analytics_storage: choice === "granted" ? "granted" : "denied"
  });
  const storedChoice = readChoice();

  window.dataLayer = window.dataLayer || [];
  window.gtag = function gtag() {
    window.dataLayer.push(arguments);
  };
  const defaultCommand = { ...defaultConsent };
  const waitForUpdate = Number(consentConfig.waitForUpdate);
  if (Number.isFinite(waitForUpdate) && waitForUpdate > 0) defaultCommand.wait_for_update = waitForUpdate;
  window.gtag("consent", "default", defaultCommand);
  if (storedChoice) window.gtag("consent", "update", consentFor(storedChoice));
  window.gtag("set", "ads_data_redaction", true);
  window.gtag("js", new Date());
  window.gtag("config", config.measurementId);

  const script = document.createElement("script");
  script.async = true;
  script.src = "https://www.googletagmanager.com/gtag/js?id=" + encodeURIComponent(config.measurementId);
  document.head.appendChild(script);

  const create = (tag, className, text) => {
    const element = document.createElement(tag);
    if (className) element.className = className;
    if (text) element.textContent = text;
    return element;
  };
  const banner = create("aside", "consent-banner");
  banner.setAttribute("role", "dialog");
  banner.setAttribute("aria-labelledby", "analytics-consent-title");
  banner.setAttribute("aria-describedby", "analytics-consent-description");
  banner.hidden = Boolean(storedChoice);
  const title = create("h2", "", "Privacy choices");
  title.id = "analytics-consent-title";
  const description = create(
    "p",
    "",
    "We use Google Analytics to understand how visitors use this website. Choose whether to allow analytics storage. Appointment form values are not read or sent."
  );
  description.id = "analytics-consent-description";
  const actions = create("div", "consent-banner__actions");
  const accept = create("button", "btn btn-solid", "Allow analytics");
  accept.type = "button";
  const decline = create("button", "consent-button", "Continue without analytics");
  decline.type = "button";
  actions.append(accept, decline);
  banner.append(title, description, actions);

  const settings = create("button", "consent-settings", "Privacy choices");
  settings.type = "button";
  settings.hidden = !storedChoice;
  settings.setAttribute("aria-label", "Change privacy choices");
  document.body.append(banner, settings);

  const choose = (choice) => {
    saveChoice(choice);
    window.gtag("consent", "update", consentFor(choice));
    banner.hidden = true;
    settings.hidden = false;
    settings.focus();
  };
  accept.addEventListener("click", () => choose("granted"));
  decline.addEventListener("click", () => choose("denied"));
  settings.addEventListener("click", () => {
    banner.hidden = false;
    settings.hidden = true;
    accept.focus();
  });
})();

(() => {
  const config = __SITE_REPUTATION || {};
  const fallback = config.fallback || {};
  const endpoint = String(config.endpoint || "").trim();
  const ratingTargets = [...document.querySelectorAll("[data-reputation-rating]")];
  const reviewCountTargets = [...document.querySelectorAll("[data-reputation-review-count]")];
  const reputationTargets = [...new Set([...ratingTargets, ...reviewCountTargets])];
  const reduced = matchMedia("(prefers-reduced-motion: reduce)").matches;

  const normalize = (value) => {
    const rating = Number(value?.rating);
    const reviewCount = Number(value?.review_count ?? value?.userRatingCount);
    if (!Number.isFinite(rating) || rating < 1 || rating > 5) return null;
    if (!Number.isInteger(reviewCount) || reviewCount < 0) return null;
    return { rating, reviewCount };
  };

  const updateSchema = ({ rating, reviewCount }) => {
    for (const element of document.querySelectorAll('script[type="application/ld+json"]')) {
      try {
        const schema = JSON.parse(element.textContent || "");
        if (!schema.aggregateRating) continue;
        schema.aggregateRating.ratingValue = rating.toFixed(1);
        schema.aggregateRating.reviewCount = String(reviewCount);
        element.textContent = JSON.stringify(schema);
      } catch {
        // Leave malformed or unrelated structured data unchanged.
      }
    }
  };

  const animate = (targets, target, format) => {
    if (reduced) {
      for (const element of targets) element.textContent = format(target);
      return;
    }
    const start = performance.now();
    const tick = (time) => {
      const progress = Math.min((time - start) / 1600, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      for (const element of targets) element.textContent = format(target * eased);
      if (progress < 1) requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  };

  const apply = (value) => {
    const normalized = normalize(value);
    if (!normalized) return false;
    animate(ratingTargets, normalized.rating, (value) => value.toFixed(1));
    animate(reviewCountTargets, normalized.reviewCount, (value) => Math.round(value).toLocaleString("en-US"));
    updateSchema(normalized);
    return true;
  };

  const reveal = (value) => {
    if (!apply(value)) apply(fallback);
    for (const element of reputationTargets) element.classList.remove("reputation-value-pending");
  };

  if (!endpoint) {
    reveal(fallback);
    return;
  }

  const url = new URL(endpoint, window.location.origin);
  fetch(url, { headers: { Accept: "application/json" } })
    .then((response) => response.ok ? response.json() : null)
    .then((value) => reveal(value))
    .catch(() => {
      reveal(fallback);
    });
})();
